import csv
genes=['P2RY12','C1QA','C1QB','C1QC','CSF1R','CX3CR1','TYROBP','AIF1','PTPRC','CD68','CD163','MRC1','LYZ','HLA-DRA','CD74','CD3D','CD3E','CD3G','TRAC','LCK','CD2','CD19','MS4A1','CD79A','CD79B','COL1A1','COL1A2','COL3A1','DCN','LUM','PECAM1','CLDN5','VWF','FLT1','EGFL7','KDR','CDH5','PDGFRB','RGS5','ACTA2','NDUFA4L2','CSPG4','NOTCH3','MPZ','PLP1','SOX10','MBP','PMP22','RPE65','BEST1','TTR','SERPINF1','MITF','RGR','RDH5','LRAT','GFAP','S100B','ALDH1L1','SLC1A2','AQP4','SOX9','PDGFRA','OLIG1','OLIG2','MOG','MAG']
for f in ['galaxy_outputs/markers_s1.tsv','galaxy_outputs/markers_s2.tsv']:
    print('\\n',f)
    found={g:[] for g in genes}
    with open(f) as fh:
        r=csv.reader(fh, delimiter='\\t'); next(r)
        for row in r:
